content="""def validate_agent_message(value):
    \"\"\"
    Pure function that validates agent message envelope structure and values.

    Returns: tuple of error-code strings (empty if valid)

    Valid envelopes must have:
    - agent_type: "model" or "human"
    - status: "DONE", "NEEDS_USER", or "BLOCKED"
    - audience: "mind"
    - trust_class: "unverified_model_output" for model, "human_agent_statement" for human
    - claims: list of objects with string text, list-of-string evidence_ids, kind in ["retrieved_fact", "inference", "proposal"]
    - artifact_refs: list of strings (may be empty)
    - uncertainties: list of strings (may be empty)
    - conflicts_with: list of strings (may be empty)
    - parent_task_id: null or non-empty string

    Does not raise; returns () on valid input.
    \"\"\"
    errors = []

    if value is None:
        return ("NULL_INPUT",)

    # Must be a dict
    if not isinstance(value, dict):
        return ("NOT_DICT",)

    # Check required fields exist and have correct types
    for field in ["agent_type", "status", "audience", "trust_class", "claims"]:
        if field not in value:
            errors.append(f"MISSING_{field.upper()}")

    # Validate agent_type
    if "agent_type" in value:
        if not isinstance(value["agent_type"], str):
            errors.append("AGENT_TYPE_NOT_STRING")
        elif value["agent_type"] not in ["model", "human"]:
            errors.append(f"INVALID_AGENT_TYPE:{value['agent_type']}")

    # Validate status
    if "status" in value:
        if not isinstance(value["status"], str):
            errors.append("STATUS_NOT_STRING")
        elif value["status"] not in ["DONE", "NEEDS_USER", "BLOCKED"]:
            errors.append(f"INVALID_STATUS:{value['status']}")

    # Validate audience
    if "audience" in value:
        if not isinstance(value["audience"], str):
            errors.append("AUDIENCE_NOT_STRING")
        elif value["audience"] != "mind":
            errors.append(f"INVALID_AUDIENCE:{value['audience']}")

    # Validate trust_class based on agent_type
    if "trust_class" in value:
        if not isinstance(value["trust_class"], str):
            errors.append("TRUST_CLASS_NOT_STRING")
        elif value["agent_type"] == "model":
            if value["trust_class"] != "unverified_model_output":
                errors.append(f"INVALID_TRUST_CLASS_FOR_MODEL:{value['trust_class']}")
        else:  # human
            if value["trust_class"] != "human_agent_statement":
                errors.append(f"INVALID_TRUST_CLASS_FOR_HUMAN:{value['trust_class']}")

    # Validate claims structure - MUST be a list, not dict
    if "claims" in value:
        if not isinstance(value["claims"], list):
            errors.append("CLAIMS_NOT_LIST")
        else:
            for claim in value["claims"]:
                # Each claim must be an object (dict) with string text, list-of-string evidence_ids, kind
                if not isinstance(claim, dict):
                    errors.append(f"INVALID_CLAIM_SHAPE:{type(claim)}")
                    continue

                # Check text field is string
                if "text" not in claim:
                    errors.append(f"MISSING_TEXT_IN_CLAIM:{claim.get('key', 'unknown')}")
                elif not isinstance(claim["text"], str):
                    errors.append(f"CLAIM_TEXT_NOT_STRING:{claim.get('key', 'unknown')}")

                # Check evidence_ids is list
                if "evidence_ids" not in claim:
                    errors.append(f"MISSING_EVIDENCE_IDS_IN_CLAIM:{claim.get('key', 'unknown')}")
                elif not isinstance(claim["evidence_ids"], list):
                    errors.append(f"EVIDENCE_IDS_NOT_LIST:{claim.get('key', 'unknown')}")

                # Check kind is one of the allowed values
                if "kind" not in claim:
                    errors.append(f"MISSING_KIND_IN_CLAIM:{claim.get('key', 'unknown')}")
                elif not isinstance(claim["kind"], str):
                    errors.append(f"CLAIM_KIND_NOT_STRING:{claim.get('key', 'unknown')}")
                elif claim["kind"] not in ["retrieved_fact", "inference", "proposal"]:
                    errors.append(f"INVALID_KIND_IN_CLAIM:{claim.get('key', 'unknown')}:{claim['kind']}")

    # Validate artifact_refs is list of strings (may be empty)
    if "artifact_refs" in value:
        if not isinstance(value["artifact_refs"], list):
            errors.append("ARTIFACT_REFS_NOT_LIST")
        else:
            for ref in value["artifact_refs"]:
                if not isinstance(ref, str):
                    errors.append(f"ARTIFACT_REF_NOT_STRING:{ref}")

    # Validate uncertainties is list of strings (may be empty)
    if "uncertainties" in value:
        if not isinstance(value["uncertainties"], list):
            errors.append("UNCERTAINTIES_NOT_LIST")
        else:
            for u in value["uncertainties"]:
                if not isinstance(u, str):
                    errors.append(f"UNCERTAINTY_NOT_STRING:{u}")

    # Validate conflicts_with is list of strings (may be empty)
    if "conflicts_with" in value:
        if not isinstance(value["conflicts_with"], list):
            errors.append("CONFLICTS_WITH_NOT_LIST")
        else:
            for c in value["conflicts_with"]:
                if not isinstance(c, str):
                    errors.append(f"CONFLICT_NOT_STRING:{c}")

    # Validate parent_task_id is null or non-empty string
    if "parent_task_id" in value:
        pt = value["parent_task_id"]
        if pt is None:
            pass  # Valid - null allowed
        elif not isinstance(pt, str):
            errors.append("PARENT_TASK_ID_NOT_STRING")
        elif len(pt) == 0:
            errors.append("PARENT_TASK_ID_EMPTY")

    return tuple(errors)

if __name__ == \"__main__\":
    # Test cases for validation
    test_cases = [
        # Valid model envelope
        {
            "agent_type": "model",
            "status": "DONE",
            "audience": "mind",
            "trust_class": "unverified_model_output",
            "claims": [
                {"text": "Fact 1", "evidence_ids": ["id1"], "kind": "retrieved_fact"},
                {"text": "Inference A", "evidence_ids": [], "kind": "inference"}
            ],
            "artifact_refs": [],
            "uncertainties": [],
            "conflicts_with": [],
            "parent_task_id": None
        },
        # Valid human envelope
        {
            "agent_type": "human",
            "status": "NEEDS_USER",
            "audience": "mind",
            "trust_class": "human_agent_statement",
            "claims": [
                {"text": "Statement 1", "evidence_ids": ["id2"], "kind": "proposal"}
            ],
            "artifact_refs": [],
            "uncertainties": [],
            "conflicts_with": [],
            "parent_task_id": None
        },
        # Missing task_id - should report MISSING_TASK_ID
        {
            "agent_type": "model",
            "status": "DONE",
            "audience": "mind",
            "trust_class": "unverified_model_output",
            "claims": [],
            "artifact_refs": [],
            "uncertainties": [],
            "conflicts_with": []
        },
        # Missing agent_type with trust_class present - should report MISSING_AGENT_TYPE without raising
        {
            "status": "DONE",
            "audience": "mind",
            "trust_class": "unverified_model_output",
            "claims": [],
            "artifact_refs": [],
            "uncertainties": [],
            "conflicts_with": []
        },
        # Claims as dict instead of list - should report CLAIMS_NOT_LIST
        {
            "agent_type": "model",
            "status": "DONE",
            "audience": "mind",
            "trust_class": "unverified_model_output",
            "claims": {"key1": "value1"},  # dict instead of list
            "artifact_refs": [],
            "uncertainties": [],
            "conflicts_with": []
        },
        # Invalid trust class for model
        {
            "agent_type": "model",
            "status": "DONE",
            "audience": "mind",
            "trust_class": "invalid_trust",  # wrong trust class
            "claims": [],
            "artifact_refs": [],
            "uncertainties": [],
            "conflicts_with": []
        },
        # Empty parent_task_id - should be rejected
        {
            "agent_type": "model",
            "status": "DONE",
            "audience": "mind",
            "trust_class": "unverified_model_output",
            "claims": [],
            "artifact_refs": [],
            "uncertainties": [],
            "conflicts_with": [],
            "parent_task_id": ""  # empty string, not null
        }
    ]

    print("Testing validate_agent_message function...")
    for i, test in enumerate(test_cases):
        result = validate_agent_message(test)
        if len(result) == 0:
            print(f"PASS: Test case {i+1} - valid envelope returned ()")
        else:
            print(f"FAIL: Test case {i+1} - expected (), got {result}")

    # Specific test for missing task_id
    result = validate_agent_message({
        "agent_type": "model",
        "status": "DONE",
        "audience": "mind",
        "trust_class": "unverified_model_output",
        "claims": [],
        "artifact_refs": [],
        "uncertainties": [],
        "conflicts_with": []
    })
    if result == ("MISSING_TASK_ID",):
        print("PASS: contract-validator cases")
    else:
        print(f"FAIL: Expected MISSING_TASK_ID, got {result}")

